CREATE TABLE IF NOT EXISTS active_roles ("id" BIGSERIAL PRIMARY KEY, "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "enable" SMALLINT NOT NULL DEFAULT 1, "user_id" BIGINT NOT NULL, "role_id" BIGINT NOT NULL);

