CREATE TABLE IF NOT EXISTS crop_diagnoses ("id" BIGSERIAL PRIMARY KEY, "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "enable" SMALLINT NOT NULL DEFAULT 1, "crop_id" BIGINT DEFAULT NULL, "farm_id" BIGINT DEFAULT NULL, "crop_name" VARCHAR(100) DEFAULT NULL, "state" VARCHAR(100) DEFAULT NULL, "district" VARCHAR(100) DEFAULT NULL, "disease_name" VARCHAR(255) DEFAULT NULL, "scientific_name" VARCHAR(255) DEFAULT NULL, "category" VARCHAR(30) DEFAULT NULL, "severity" VARCHAR(20) DEFAULT NULL, "urgency" VARCHAR(20) DEFAULT NULL, "confidence" DECIMAL(4,3) DEFAULT NULL, "language" VARCHAR(10) DEFAULT NULL, "model_used" VARCHAR(100) DEFAULT NULL, "safety_flags" INTEGER NOT NULL DEFAULT 0, "result" JSONB DEFAULT NULL, "user_id" BIGINT NOT NULL);

