CREATE TABLE IF NOT EXISTS crop_profitability ("id" BIGSERIAL PRIMARY KEY, "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "enable" SMALLINT NOT NULL DEFAULT 1, "crop_type" VARCHAR(100) NOT NULL, "variety" VARCHAR(200) DEFAULT NULL, "state" VARCHAR(100) NOT NULL, "district" VARCHAR(100) DEFAULT NULL, "year" INTEGER NOT NULL, "season" VARCHAR(50) DEFAULT NULL, "avg_profit_per_acre" DECIMAL(10,2) NOT NULL, "min_profit_per_acre" DECIMAL(10,2) DEFAULT NULL, "max_profit_per_acre" DECIMAL(10,2) DEFAULT NULL, "seed_cost" DECIMAL(10,2) DEFAULT NULL, "fertilizer_cost" DECIMAL(10,2) DEFAULT NULL, "pesticide_cost" DECIMAL(10,2) DEFAULT NULL, "labor_cost" DECIMAL(10,2) DEFAULT NULL, "irrigation_cost" DECIMAL(10,2) DEFAULT NULL, "equipment_cost" DECIMAL(10,2) DEFAULT NULL, "other_costs" DECIMAL(10,2) DEFAULT NULL, "total_investment_cost" DECIMAL(10,2) DEFAULT NULL, "avg_revenue_per_acre" DECIMAL(10,2) DEFAULT NULL, "roi_percentage" DECIMAL(5,2) DEFAULT NULL, "break_even_yield" DECIMAL(10,2) DEFAULT NULL, "profit_margin" DECIMAL(5,2) DEFAULT NULL, "risk_level" VARCHAR(20) DEFAULT NULL, "price_risk_score" DECIMAL(3,2) DEFAULT NULL, "yield_risk_score" DECIMAL(3,2) DEFAULT NULL, "market_demand" VARCHAR(20) DEFAULT NULL, "competition_level" VARCHAR(20) DEFAULT NULL, "data_source" VARCHAR(100) DEFAULT NULL, "sample_size" INTEGER DEFAULT NULL);

