EFAULT NULL, "shc_fetched_at" TIMESTAMP DEFAULT NULL, "shc_partial_data" BOOLEAN DEFAULT NULL DEFAULT false, "shc_unavailable_styles" TEXT[] DEFAULT NULL, "user_id" BIGINT NOT NULL, "owner_id" BIGINT NOT NULL);

