_risk" DECIMAL(5,2) DEFAULT NULL, "confidence_score" DECIMAL(3,2) DEFAULT NULL, "key_assumptions" JSONB DEFAULT NULL, "sensitivity_analysis" JSONB DEFAULT NULL, "recommendation" TEXT DEFAULT NULL, "optimization_suggestions" JSONB DEFAULT NULL, "market_data_source" VARCHAR(100) DEFAULT NULL, "breed_performance_data_source" VARCHAR(100) DEFAULT NULL, "animal_id" BIGINT DEFAULT NULL, "user_id" BIGINT DEFAULT NULL);

