CREATE TABLE IF NOT EXISTS ndap_ingestion_runs ("id" BIGSERIAL PRIMARY KEY, "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "enable" SMALLINT NOT NULL DEFAULT 1, "file_name" VARCHAR(255) NOT NULL, "file_hash" VARCHAR(64) NOT NULL UNIQUE, "started_at" TIMESTAMP NOT NULL, "completed_at" TIMESTAMP DEFAULT NULL, "status" VARCHAR(20) NOT NULL, "records_ingested" INTEGER DEFAULT NULL DEFAULT 0, "error_message" TEXT DEFAULT NULL);

