CREATE TABLE IF NOT EXISTS opportunity_costs ("id" BIGSERIAL PRIMARY KEY, "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "enable" SMALLINT NOT NULL DEFAULT 1, "location_state" VARCHAR(100) NOT NULL, "location_district" VARCHAR(100) DEFAULT NULL, "primary_crop" VARCHAR(100) NOT NULL, "alternative_crop" VARCHAR(100) NOT NULL, "season" VARCHAR(50) DEFAULT NULL, "year" INTEGER DEFAULT NULL, "primary_crop_profit" DECIMAL(10,2) NOT NULL, "alternative_crop_profit" DECIMAL(10,2) NOT NULL, "profit_difference" DECIMAL(10,2) NOT NULL, "primary_crop_investment" DECIMAL(10,2) DEFAULT NULL, "alternative_crop_investment" DECIMAL(10,2) DEFAULT NULL, "investment_difference" DECIMAL(10,2) DEFAULT NULL, "primary_crop_roi" DECIMAL(5,2) DEFAULT NULL, "alternative_crop_roi" DECIMAL(5,2) DEFAULT NULL, "roi_difference" DECIMAL(5,2) DEFAULT NULL, "primary_crop_risk" VARCHAR(20) DEFAULT NULL, "alternative_crop_risk" VARCHAR(20) DEFAULT NULL, "risk_factor" DECIMAL(3,2) DEFAULT NULL, "primary_crop_demand" VARCHAR(20) DEFAULT NULL, "alternative_crop_demand" VARCHAR(20) DEFAULT NULL, "market_stability_comparison" TEXT DEFAULT NULL, "recommended_choice" VARCHAR(100) DEFAULT NULL, "recommendation_confidence" DECIMAL(3,2) DEFAULT NULL, "recommendation_reasoning" TEXT DEFAULT NULL, "soil_suitability_comparison" JSONB DEFAULT NULL, "water_requirement_comparison" JSONB DEFAULT NULL, "labor_requirement_comparison" JSONB DEFAULT NULL);

CREATE TABLE IF NOT EXISTS payment_milestones ("id" BIGSERIAL PRIMARY KEY, "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "enable" SMALLINT NOT NULL DEFAULT 1, "milestone_type" VARCHAR(50) NOT NULL, "amount" DECIMAL(10,2) NOT NULL, "due_date" TIMESTAMP NOT NULL, "paid_date" TIMESTAMP DEFAULT NULL, "status" VARCHAR(50) NOT NULL DEFAULT 'pending', "payment_method" VARCHAR(100) DEFAULT NULL, "transaction_id" VARCHAR(255) DEFAULT NULL, "booking_id" BIGINT NOT NULL);

CREATE TABLE IF NOT EXISTS pest_disease_alerts ("id" BIGSERIAL PRIMARY KEY, "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "enable" SMALLINT NOT NULL DEFAULT 1, "pest_disease_name" VARCHAR(255) NOT NULL, "alert_type" VARCHAR(50) NOT NULL, "severity" VARCHAR(50) NOT NULL, "description" TEXT NOT NULL, "crop_stage" VARCHAR(100) NOT NULL, "weather_conditions" TEXT DEFAULT NULL, "organic_recommendations" TEXT DEFAULT NULL, "chemical_recommendations" TEXT DEFAULT NULL, "prevention_measures" TEXT DEFAULT NULL, "timing_instructions" TEXT DEFAULT NULL, "notification_sent" SMALLINT DEFAULT 0, "notification_sent_at" TIMESTAMP DEFAULT NULL, "is_resolved" SMALLINT DEFAULT 0, "resolved_at" TIMESTAMP DEFAULT NULL, "crop_id" BIGINT NOT NULL, "farm_id" BIGINT NOT NULL);

