CREATE TABLE IF NOT EXISTS satellite_observations ("id" BIGSERIAL PRIMARY KEY, "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "enable" SMALLINT NOT NULL DEFAULT 1, "scene_id" VARCHAR(120) NOT NULL, "observed_on" DATE NOT NULL, "source" VARCHAR(50) NOT NULL DEFAULT 'sentinel-2-l2a', "ndvi" DECIMAL(5,3) DEFAULT NULL, "ndmi" DECIMAL(5,3) DEFAULT NULL, "ndre" DECIMAL(5,3) DEFAULT NULL, "clear_pct" DECIMAL(5,1) DEFAULT NULL, "pixels" INTEGER DEFAULT NULL, "state" VARCHAR(100) DEFAULT NULL, "district" VARCHAR(100) DEFAULT NULL, "farm_id" BIGINT NOT NULL);

