CREATE TABLE IF NOT EXISTS veterinarians ("id" BIGSERIAL PRIMARY KEY, "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "enable" SMALLINT NOT NULL DEFAULT 1, "added_by_user_id" BIGINT DEFAULT NULL, "name" VARCHAR(255) NOT NULL, "clinic_name" VARCHAR(255) DEFAULT NULL, "specialization" VARCHAR(100) DEFAULT NULL, "species_supported" TEXT DEFAULT NULL, "phone" VARCHAR(20) NOT NULL, "whatsapp" VARCHAR(20) DEFAULT NULL, "email" VARCHAR(255) DEFAULT NULL, "location_state" VARCHAR(100) DEFAULT NULL, "location_district" VARCHAR(100) DEFAULT NULL, "address" TEXT DEFAULT NULL, "available_now" SMALLINT NOT NULL DEFAULT 1, "verified" SMALLINT NOT NULL DEFAULT 0, "rating" DECIMAL(3,2) DEFAULT 0, "total_ratings" INTEGER DEFAULT 0, "notes" TEXT DEFAULT NULL);

CREATE TABLE IF NOT EXISTS voice_assist_logs ("id" BIGSERIAL PRIMARY KEY, "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "enable" SMALLINT NOT NULL DEFAULT 1, "source" VARCHAR(20) NOT NULL DEFAULT 'text', "task" VARCHAR(50) DEFAULT NULL, "ui_lang" VARCHAR(10) DEFAULT NULL, "language_detected" VARCHAR(10) DEFAULT NULL, "mime_type" VARCHAR(50) DEFAULT NULL, "audio_bytes" INTEGER DEFAULT NULL, "duration_ms" INTEGER DEFAULT NULL, "transcript" TEXT DEFAULT NULL, "intent" VARCHAR(20) DEFAULT NULL, "model_used" VARCHAR(100) DEFAULT NULL, "status" VARCHAR(20) NOT NULL DEFAULT 'ok', "error" TEXT DEFAULT NULL, "latency_ms" INTEGER DEFAULT NULL, "user_id" BIGINT NOT NULL);

CREATE TABLE IF NOT EXISTS weather_alerts ("id" BIGSERIAL PRIMARY KEY, "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "enable" SMALLINT NOT NULL DEFAULT 1, "state" VARCHAR(255) NOT NULL, "district" VARCHAR(255) DEFAULT NULL, "alert_type" VARCHAR(255) NOT NULL, "severity" VARCHAR(255) NOT NULL, "message" TEXT NOT NULL, "recommendation" TEXT DEFAULT NULL, "valid_from" TIMESTAMP NOT NULL, "valid_until" TIMESTAMP NOT NULL, "is_active" SMALLINT DEFAULT 1, "farm_id" BIGINT DEFAULT NULL);

CREATE TABLE IF NOT EXISTS weather_forecasts ("id" BIGSERIAL PRIMARY KEY, "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "enable" SMALLINT NOT NULL DEFAULT 1, "latitude" DECIMAL(10,8) NOT NULL, "longitude" DECIMAL(11,8) NOT NULL, "location_name" VARCHAR(255) DEFAULT NULL, "state" VARCHAR(100) DEFAULT NULL, "district" VARCHAR(100) DEFAULT NULL, "forecast_date" DATE NOT NULL, "forecast_time" TIMESTAMP DEFAULT NULL, "forecast_type" VARCHAR(50) DEFAULT NULL, "temperature_min" DECIMAL(5,2) DEFAULT NULL, "temperature_max" DECIMAL(5,2) DEFAULT NULL, "temperature_avg" DECIMAL(5,2) DEFAULT NULL, "feels_like" DECIMAL(5,2) DEFAULT NULL, "rainfall_probability" DECIMAL(5,2) DEFAULT NULL, "rainfall_amount" DECIMAL(8,2) DEFAULT NULL, "rainfall_intensity" VARCHAR(50) DEFAULT NULL, "wind_speed" DECIMAL(6,2) DEFAULT NULL, "wind_direction" VARCHAR(50) DEFAULT NULL, "wind_gust" DECIMAL(6,2) DEFAULT NULL, "humidity" DECIMAL(5,2) DEFAULT NULL, "pressure" DECIMAL(8,2) DEFAULT NULL, "dew_point" DECIMAL(5,2) DEFAULT NULL, "cloud_cover" DECIMAL(5,2) DEFAULT NULL, "visibility" DECIMAL(6,2) DEFAULT NULL, "uv_index" DECIMAL(4,2) DEFAULT NULL, "solar_radiation" DECIMAL(8,2) DEFAULT NULL, "weather_condition" VARCHAR(100) DEFAULT NULL, "weather_description" TEXT DEFAULT NULL, "weather_icon" VARCHAR(50) DEFAULT NULL, "evapotranspiration" DECIMAL(6,2) DEFAULT NULL, "soil_moisture_index" DECIMAL(5,2) DEFAULT NULL, "growing_degree_days" DECIMAL(6,2) DEFAULT NULL, "data_source" VARCHAR(100) DEFAULT NULL, "source_forecast_id" VARCHAR(255) DEFAULT NULL, "data_quality_score" DECIMAL(3,2) DEFAULT NULL, "fetched_at" TIMESTAMP DEFAULT NULL, "expires_at" TIMESTAMP DEFAULT NULL);

